/// Configure global print options for numerical array output.
/// Any `None` argument leaves that option unchanged. Panics if a provided
/// argument does not satisfy the documented constraints.
fn set_printoptions(
    precision:  Option<u8>,
    threshold:  Option<u8>,
    edgeitems:  Option<u8>,
    linewidth:  Option<u8>,
    suppress:   Option<bool>,
    nanstr:     Option<String>,
    infstr:     Option<String>,
    sign:       Option<String>,
    floatmode:  Option<String>,
    legacy:     Option<String>,
) {
    let mut opts = PRINT_OPTIONS.lock().unwrap();

    if let Some(p) = precision {
        assert!(p > 0, "precision must be strictly positive");
        opts.precision = p;
    }
    if let Some(t) = threshold {
        assert!(t > 0, "threshold must be strictly positive");
        opts.threshold = t;
    }
    if let Some(e) = edgeitems {
        assert!(e > 0, "edgeitems must be strictly positive");
        opts.edgeitems = e;
    }
    if let Some(w) = linewidth {
        assert!(w > 0, "linewidth must be strictly positive");
        opts.linewidth = w;
    }
    if let Some(s) = suppress {
        opts.suppress = s;
    }
    if let Some(ns) = nanstr {
        assert!(!ns.is_empty(), "nan string must be non-empty");
        opts.nanstr = ns;
    }
    if let Some(is) = infstr {
        assert!(!is.is_empty(), "infinity string must be non-empty");
        opts.infstr = is;
    }
    if let Some(sign_str) = sign {
        assert!(sign_str.len() == 1, "sign must be a single character");
        let ch = sign_str.chars().next().unwrap();
        assert!(ch == '-' || ch == '+' || ch == ' ',
                "sign must be one of '-', '+', or ' '");
        opts.sign = ch;
    }
    if let Some(fm) = floatmode {
        let mode = FloatMode::from_str(&fm)
            .expect("float mode must be one of \"fixed\", \"unique\", \"maxprec\", or \"maxprec_equal\"");
        opts.floatmode = mode;
    }
    if let Some(lm) = legacy {
        let mode = LegacyMode::from_str(&lm)
            .expect("legacy mode must be one of \"1.13\", \"1.21\", \"1.25\", \"2.1\", or \"2.2\"");
        opts.legacy = mode;
    }
    // Successfully updated global print options.
}

