    #[test]
    fn test_set_printoptions_updates() {
        // Reset to defaults first.
        {
            let mut opts = PRINT_OPTIONS.lock().unwrap();
            *opts = PrintOptions::default();
        }

        set_printoptions(
            Some(5),
            Some(200),
            Some(4),
            Some(100),
            Some(true),
            Some("NaN".to_string()),
            Some("Inf".to_string()),
            Some("+".to_string()),
            Some("fixed".to_string()),
            Some("2.1".to_string()),
        );

        let opts = PRINT_OPTIONS.lock().unwrap();
        assert_eq!(opts.precision, 5);
        assert_eq!(opts.threshold, 200);
        assert_eq!(opts.edgeitems, 4);
        assert_eq!(opts.linewidth, 100);
        assert_eq!(opts.suppress, true);
        assert_eq!(opts.nanstr, "NaN");
        assert_eq!(opts.infstr, "Inf");
        assert_eq!(opts.sign, '+');
        if let FloatMode::Fixed = opts.floatmode {} else { panic!("floatmode not set to Fixed"); }
        if let LegacyMode::V2_1 = opts.legacy {} else { panic!("legacy not set to V2_1"); }
    }

